/* Four-port offline collective collector.
 *
 * This is the finite packet-replay implementation of the contract in
 * PROTOCOL.md: no socket, NIC, GPU or switch is touched.  Ingress frames are
 * validated strictly, admitted into a bounded retention pool, aggregated per
 * collective, and drained through a deterministic egress priority that owns
 * cumulative upstream acknowledgment, mode-2 reliability translation, mode-3
 * result retransmission and local backpressure. */
#include "switch_ctx.h"

#include <stdlib.h>
#include <string.h>

#define PSN_MASK EPIC_PSN_MASK
#define ALL_MASK 0xfu

/* ------------------------------------------------------------------ *
 * Sequence-space mappings
 * ------------------------------------------------------------------ */

static int ordinal_excluding(int dst, int src) {
    return src - (dst < src ? 1 : 0);
}

static int rank_from_ordinal(int dst, int ordinal) {
    int n = 0;
    for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
        if (r == dst) {
            continue;
        }
        if (n == ordinal) {
            return r;
        }
        n++;
    }
    return 0;
}

void epic_init_outc(epic_ctx_t *ctx) {
    uint32_t K = ctx->K;
    for (int d = 0; d < EPIC_STAR4_HOSTS; d++) {
        uint32_t n;
        switch ((epic_primitive_t)ctx->kind) {
        case EPIC_PRIM_ALLREDUCE:
        case EPIC_PRIM_BARRIER:
            n = K;
            if (ctx->kind == EPIC_PRIM_BARRIER) {
                n = 1; /* barrier is a single segment for every rank */
            }
            break;
        case EPIC_PRIM_REDUCE:
            n = (d == ctx->root) ? K : 0;
            break;
        case EPIC_PRIM_BCAST:
            n = (d == ctx->root) ? 0 : K;
            break;
        case EPIC_PRIM_ALLGATHER:
            n = 3 * K;
            break;
        case EPIC_PRIM_REDUCESCATTER:
            n = K / 4;
            break;
        default:
            n = 0;
            break;
        }
        ctx->outc[d] = n;
    }
}

/* Logical input segment owning receiver d's output record q. */
static uint32_t rec_p(const epic_ctx_t *ctx, int d, uint32_t q) {
    switch ((epic_primitive_t)ctx->kind) {
    case EPIC_PRIM_ALLGATHER:
        return q / 3;
    case EPIC_PRIM_REDUCESCATTER:
        return (uint32_t)d * ctx->m + q;
    case EPIC_PRIM_BARRIER:
        return 0;
    default:
        (void)d;
        return q;
    }
}

/* Source whose value receiver d's output record q carries (allgather only). */
static int rec_src(const epic_ctx_t *ctx, int d, uint32_t q) {
    if (ctx->kind == (int)EPIC_PRIM_ALLGATHER) {
        return rank_from_ordinal(d, (int)(q % 3));
    }
    (void)d;
    (void)q;
    return -1;
}

/* ------------------------------------------------------------------ *
 * Retention pool
 * ------------------------------------------------------------------ */

uint8_t *epic_slot_base(const epic_ctx_t *ctx, uint32_t index) {
    return ctx->pool + (size_t)index * ctx->stride;
}

int epic_slot_index(const epic_ctx_t *ctx, uint32_t p, uint32_t *idx) {
    uint32_t i = p % ctx->N;
    *idx = i;
    return ctx->used[i] && ctx->slot_p[i] == p;
}

static int complete_at(const epic_ctx_t *ctx, uint32_t p) {
    uint32_t i;
    if (!epic_slot_index(ctx, p, &i)) {
        return 0;
    }
    return ctx->slot_mask[i] == ctx->req_mask;
}

